entries[374194] = { ["name"] = "Moosmammut", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Dieses Mammut wurde über Tausende von Jahren in Stein konserviert und durch Bronzemagie beinahe zurück in ein Fossil gealtert.\"\nBeute von:\nGewölbe von Zskera" }
