entries[374204] = { ["name"] = "Steinbalgpacktier des Forschers", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Ein wahrer Entdecker bleibt nie lange an einem Ort. Ein zuverlässiges Packtier mit kräftigem Rücken und starken Beinen ist für die Reisen unerlässlich.\"\nVerkäuferin:\nVersorgerin Aristta\nZone:\nThaldraszus\nKosten:\n20.000" }
