entries[374352] = { ["name"] = "Energiebombe", ["text"] = "100 Meter Reichweite\nSofort\nDas Echo von Doragosa markiert einen Spielercharakter für 6 Sek. mit arkaner Energie. Wenn die ' Energiebombe ' abläuft, fügt sie allen Spielercharakteren innerhalb von 8 Metern 4359790 Arkanschaden zu.\n\nBelegt das Ziel mit ' Überwältigende Kraft '." }
entries[374355] = { ["name"] = "Erhitzte Schwünge", ["text"] = "Sofort\nDer Schmiedemeister führt zwei Schwünge gegen sein aktuelles Ziel aus, die jeweils 40 körperlichen Schaden verursachen, und stößt das Ziel weg.\n\nDann springt er zur Position des Ziels und lässt seinen entzündeten Hammer niederkrachen, der Spielercharakteren innerhalb von 8 Metern um den Einschlag 100 körperlichen sowie 35 Feuerschaden zufügt." }
entries[374358] = { ["name"] = "Tücke", ["text"] = "'Göttlicher Stern' und 'Strahlenkranz' verursachen jetzt Schattenschaden und erhalten einen zusätzlichen Effekt:\n\nTückischer Stern :\n'Göttlicher Stern' fügt Gegnern in seiner Bahn zusätzlich (120% der Zaubermacht) Schattenschaden im Verlauf von 6 Sek. zu. 'Göttlicher Stern' verursacht jedes Mal, wenn ein Gegner getroffen wird, 10% zusätzlichen Schaden, bis zu 100%.\n\nTückischer Strahlenkranz :\nVon 'Strahlenkranz' verletzte Gegner erleiden im Verlauf von 6 Sek. zusätzliche (120% der Zaubermacht) Schattenschaden, wenn sie sich in seinem Weg befinden. Bei jedem Treffer wird die Abklingzeit von 'Strahlenkranz' um 3 Sek. verringert, bis zu 15 Sek." }
