entries[374525] = { ["name"] = "Konvergentes Prisma", ["text"] = "Wirken in 2 sek.\nTools: Juwelierswerkzeuge\nReagenzien:\nLeuchtende Titanenkugel , Endlosdiamant , Elementarharmonie , Projektionsprisma\nSchatz:\nUnauffälliges Lesezeichen\nZone:\nThaldraszus\n\nKonvergentes Prisma\nSpielzeug\nBenutzen: Nehmt das verzauberte Prisma fest in die Hand, um einen sehr präzisen Lichtstrahl zu lenken.\n\nDer Strahl ist nur für Mitglieder Eurer Gruppe oder Eures Schlachtzugs sichtbar. (5 Sek. Abklingzeit)" }
