entries[375046] = { ["name"] = "Lodernde Aegis", ["text"] = "100 Meter Reichweite\nSofort\nDer Schmiedemeister schleudert den frisch geschmiedeten Schild auf einen Spielercharakter, was innerhalb von 3.5 Metern 2909339 Feuerschaden sowie zusätzlich 4 Sek. lang alle 1 Sek. 872802 Feuerschaden verursacht.\n\nEs werden in vier Richtungen flammende Eruptionen ausgelöst." }
