entries[375063] = { ["name"] = "\"Strassbesetzte\" Sonnenbrille", ["text"] = "Wirken in 2 sek.\nTools: Juwelierswerkzeuge\nReagenzien:\nYsmaragd (2), Endlosdiamant , Rahmenlose Linse (2), Elementarharmonie\nAngeln:\nDrakonisches Rezept in der Flasche\nVorlage:\nErhältlich im Auktionshaus\n\n\"Strassbesetzte\" Sonnenbrille\nKosmetisch\nWird beim Anlegen gebunden\nKopf Kosmetisch\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen." }
