entries[375168] = { ["name"] = "Ledergebundene Trommeln", ["text"] = "Wirken in 2 sek.\nReagenzien:\nWiderstandsfähiges Leder (100), Adamantschuppen (100)\nBerufsausbilder:\nLederverarbeitung der Dracheninseln (15)\nKosten:\n50\n\nWildbalgtrommeln\nBenutzen: Erhöht das Tempo aller Gruppen- und Schlachtzugsmitglieder um 15%. Hält 40 Sek. lang an.\n\nWenn der Effekt endet, sind die Betroffenen erschöpft und können 10 Min. lang nicht mehr von 'Kampfrausch', 'Heldentum' oder ähnlichen Effekten profitieren. (2 Min Abklingzeit)\n61" }
entries[375171] = { ["name"] = "Gnollzelt", ["text"] = "Wirken in 2 sek.\nReagenzien:\nUrzeitbärrückgrat , Widerstandsfähiges Leder (200), Dichter Balg (20), Schimmernder Schuppenbalg (15)\nBeute von:\nGnolle\nMuster:\nErhältlich im Auktionshaus\n\nGnollzelt\nSpielzeug\nBenutzen: Baut ein Gnollzelt auf, in dem Ihr Euch ausruhen und entspannen könnt. (2 Min Abklingzeit)" }
entries[375172] = { ["name"] = "Sitzsack der Tuskarr", ["text"] = "Wirken in 2 sek.\nReagenzien:\nGeschwungene Vogelfeder (100), Widerstandsfähiges Leder (200), Dichter Balg (30)\nVerkäufer:\nMurik\nZone:\nAzurblaues Gebirge\nTuskarr von Iskaara - Ruhmstufe 23\nKosten:\n500\n\nVerkäufer:\nRokkutuk\nZone:\nAzurblaues Gebirge\nTuskarr von Iskaara - Ruhmstufe 23\nKosten:\n500\n\nSitzsack der Tuskarr\nSpielzeug\nBenutzen: Platziert einen Sitzsack, der 2 Min. lang bestehen bleibt, um auf ihm zu sitzen. (2 Min Abklingzeit)\n\"Das edelste Erholungsgerät der Tuskarr.\"" }
