entries[375195] = { ["name"] = "Feuerfeste Schürze", ["text"] = "Wirken in 2 sek.\nReagenzien:\nEifer des Handwerkers (225), Makellose Protodrachenschuppe (10), Adamantschuppen (80), Steinkrustenbalg (8)\nOptionale Reagenzien:\nGlorreiche Einsicht (#93)\nVerkäufer:\nRüstmeister Huseng\nZone:\nEbenen von Ohn'ahra\nZentauren der Maruuk - Ruhmstufe 18\nKosten:\n200\n\nFeuerfeste Schürze\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Brust (1)Zubehör für Schmiedekunst\n+ 29 Mehrfachherstellung\nAnlegen: +6 Fertigkeit in Schmiedekunst der Dracheninseln" }
entries[375196] = { ["name"] = "Hut des Alchemieexperten", ["text"] = "Wirken in 2 sek.\nReagenzien:\nEifer des Handwerkers (225), Erweckte Luft (12), Widerstandsfähiges Leder (80), Frostbissschuppen (8)\nOptionale Reagenzien:\nGlorreiche Einsicht (#93)\nVerkäufer:\nRüstmeister Huseng\nZone:\nEbenen von Ohn'ahra\nZentauren der Maruuk - Ruhmstufe 18\nKosten:\n200\n\nHut des Alchemieexperten\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Kopf (1)Zubehör für Alchemie\n+ 29 Mehrfachherstellung\nAnlegen: +6 Fertigkeit in Alchemie der Dracheninseln" }
entries[375197] = { ["name"] = "Lodergugel", ["text"] = "Wirken in 2 sek. 3\nReagenzien:\nFeurige Seele , Erwecktes Feuer (10), Widerstandsfähiges Leder (100), Erdschimmerschuppen (16), Funke (#247)\nOptionale Reagenzien:\nSpezialisierung:\nUrzeitliche Lederverarbeitung - Elementarmeisterschaft\n\nLodergugel\nWird beim Aufheben gebunden\nKopf Leder\n282 Rüstung\n+257 [Beweglichkeit oder Intelligenz]+416 Ausdauer\nErhöht Eure Tempowertung um + 200.\nErhöht Eure Meisterschaftswertung um + 273.\nHaltbarkeit 100 / 100\nAnlegen: Im Kampf seid Ihr in intensive Hitze gehüllt, die Gegner in der Nähe verbrennt und alle 3 Sek. 944 Feuerschaden verursacht, der auf alle Gegner in der Nähe aufgeteilt wird.\n\nDer Schaden erhöht sich pro getroffenem Gegner, bis zu 5 Gegner.\n70" }
entries[375199] = { ["name"] = "Welkwurzfoliant", ["text"] = "Wirken in 2 sek. 3\nReagenzien:\nErweckter Verfall (15), Weitschreitersehne (2), Widerstandsfähiges Leder (100), Steinkrustenbalg (14), Funke (#247)\nOptionale Reagenzien:\nMit Energie erfüllen (#126) , Sekundärwerte anpassen (#227) , Glorreiche Einsicht (#93)\nDieses widerwärtige Muster erfordert einen mit mächtiger Verfallmagie erfüllten Altar, den es angeblich tief in der Brackenfellhöhle geben soll.\nSpezialisierung:\nUrzeitliche Lederverarbeitung - Verrottender Griff\n\nWelkwurzfoliant\nWird beim Aufheben gebunden\nIn Schildhand geführt\n+394 Intelligenz\n+208 Ausdauer\n+ 120 Zufallswert 1\n+ 120 Zufallswert 2\nAnlegen: Wenn Ihr mit Zaubern und Fähigkeiten Naturschaden verursacht, besteht eine geringe Chance, Euer Ziel mit 'Foliantengebundene Fäulnis' zu belegen, was ihm alle 2 Sek. 1780 Naturschaden zufügt und seine Bewegungsgeschwindigkeit um 30% verringert. Hält 10 Sek. lang an.\n70" }
entries[375201] = { ["name"] = "Krallenreißen", ["text"] = "10 Meter Reichweite\nWirken in 2 sek. 12 sek. Abklingzeit\nFügt allen Gegnern vor dem Zaubernden 25 körperlichen Schaden zu.\n\nFügt allen Gegnern vor dem Zaubernden 15 Sek. lang alle 3 Sek. körperlichen Schaden zu." }
