entries[375428] = { ["name"] = "Flammen erwecken", ["text"] = "Sofort\nMit seinem letzten Atemzug ruft der Schmiedemeister nach den ruhelosen Flammen.\n\nEin gigantischer Feuerball wird aus der Schmiede geschleudert, fügt Spielercharakteren innerhalb von 10 Metern um den Einschlagsort 200 Feuerschaden zu und erschafft Ignarus, die erweckte Schmiede. Die Wucht des Einschlags stößt alle Spielercharakter zurück und verursacht 20 Feuerschaden." }
entries[375429] = { ["name"] = "Flammen erwecken", ["text"] = "Unbegrenzte Reichweite\nSofort\nMit seinem letzten Atemzug ruft der Schmiedemeister nach den ruhelosen Flammen.\n\nEin gigantischer Feuerball wird aus der Schmiede geschleudert, fügt Spielercharakteren innerhalb von 10 Metern um den Einschlagsort 200 Feuerschaden zu und erschafft Ignarus, die erweckte Schmiede. Die Wucht des Einschlags stößt alle Spielercharakter zurück und verursacht 20 Feuerschaden." }
entries[375430] = { ["name"] = "Sehne durchtrennen", ["text"] = "Nahkampfreichweite\nSofort\nDer Legionär schlitzt Gegner auf, verursacht 15 körperlichen Schaden und verringert die Bewegungsgeschwindigkeit betroffener Spielercharaktere 3 Sek. lang um 20%." }
entries[375431] = { ["name"] = "Brennender Ansturm", ["text"] = "Sofort 8 sek. Abklingzeit\nMagmahauer stürmt vorwärts, verursacht 8485573 Feuerschaden und stößt alle Spielercharaktere zurück, die ihm im Weg stehen. Am Ende des Ansturms entfesselt Magmahauer eine ' Lavawelle ' pro Magmatentakel ." }
entries[375435] = { ["name"] = "Atem des Todes", ["text"] = "Sofort\nVon Yseras 'Atem des Todes' entkräftet. Erhöht den erlittenen Schaden um 200% und verringert den verursachten Schaden um 50%." }
