entries[375444] = { ["name"] = "Magmabeladener Hammer", ["text"] = "Sofort\nErfüllt den Hammer des Zaubernden mit Magma, sodass er mit jedem Angriff 'Zähflüssiges Magma' anwendet.\n\n'Zähflüssiges Magma' verursacht 10 Sek. lang alle 2 Sek. 5 Feuerschaden. Bei 3 Stapeln explodiert 'Zähflüssiges Magma' und bildet in der Nähe des Ziels Magmapfützen." }
